mapper.select:
SELECT interview_id FROM hr_exit_interview
WHERE tenant_id = #{tenantId} AND interview_id = #{identifier}
FOR UPDATE

mapper.update:
UPDATE hr_exit_interview
SET settlement_id = #{record.settlementId}, interviewer_id = #{record.interviewerId},
    interview_time = #{record.interviewTime}, location = #{record.location},
    leaving_reason = #{record.leavingReason}, employee_feedback = #{record.employeeFeedback},
    manager_comment = #{record.managerComment},
    improvement_items = #{record.improvementItems,typeHandler=com.baomidou.mybatisplus.extension.handlers.JacksonTypeHandler},
    attachment_file_ids = #{record.attachmentFileIds,typeHandler=com.baomidou.mybatisplus.extension.handlers.JacksonTypeHandler},
    status = #{record.status}, version = version + 1,
    update_by = #{record.updateBy}, update_time = #{record.updateTime}
WHERE tenant_id = #{record.tenantId} AND interview_id = #{record.interviewId}
  AND employee_id = #{record.employeeId} AND lifecycle_application_id = #{record.lifecycleApplicationId}
  AND status = 'DRAFT' AND version = #{expectedVersion}

UPDATE sys_file SET biz_type = 'HR_EXIT_INTERVIEW', biz_id = #{interviewId}, file_hash = #{hash}
WHERE tenant_id = #{tenantId} AND file_id = #{fileId} AND file_type = 'HR_EXIT_INTERVIEW'
  AND deleted = 0 AND biz_type IS NULL AND biz_id IS NULL AND url = ''
